cat << 'EOF' > test_cellpose_correct_sop.py
import os, pandas as pd, tifffile, numpy as np
from skimage.measure import regionprops
from cellpose import models

dark = tifffile.imread('/task/input/flatfield/dark.tif').astype(float)
flat1 = tifffile.imread('/task/input/flatfield/flat_ch1.tif').astype(float)
norm_flat1 = (flat1 - dark) / np.mean(flat1 - dark)
def correct_ch1(img):
    return np.maximum(0, (img.astype(float) - dark) / norm_flat1)

model = models.CellposeModel(model_type='nuclei', gpu=False)
ann_wells = ['A06', 'A11', 'A12', 'C12', 'D10', 'E05', 'G07', 'H12']

wells_data = {}
for well in ann_wells:
    ann = pd.read_csv(f'/task/input/annotations/{well}.tsv', sep='\t')
    img = tifffile.imread(f'/task/input/images/{well}_ch1.tif')
    wells_data[well] = (correct_ch1(img), len(ann))

for diam in [14, 15, 16, 17]:
    for flow_th in [0.4, 0.8]:
        for cell_th in [-0.5, 0.0]:
            res = []
            all_pass = True
            for well in ann_wells:
                img, man = wells_data[well]
                masks, _, _ = model.eval(img, diameter=diam, flow_threshold=flow_th, cellprob_threshold=cell_th, channels=[0,0])
                props = regionprops(masks)
                valid = 0
                for p in props:
                    if p.bbox[2] >= 320 or p.bbox[3] >= 320:
                        continue
                    touches_top_left = (p.bbox[0] == 0 or p.bbox[1] == 0)
                    if touches_top_left:
                        if p.area < 20:
                            continue
                    else:
                        if p.area < 45 or p.minor_axis_length < 7.0:
                            continue
                    valid += 1
                diff = abs(valid - man)
                allowed = max(3, 0.1 * man)
                if diff > allowed:
                    all_pass = False
                res.append((well, man, valid, diff, allowed))
            n_pass = sum(1 for x in res if x[3] <= x[4])
            print(f'diam={diam}, flow={flow_th}, cell={cell_th} -> Pass={n_pass}/8')
            for x in res:
                print(f'   {x[0]}: man={x[1]}, c={x[2]}, diff={x[3]}, allowed={x[4]:.1f}, pass={x[3]<=x[4]}')
            if all_pass:
                print('*** ALL 8 PASSED! ***')
                break
        if all_pass: break
    if all_pass: break
EOF
python3 test_cellpose_correct_sop.py

